<div class="grid gap-5 md:grid-cols-4"><?php foreach ($stats as $label => $value): ?><div class="rounded-3xl border border-white/10 bg-white/5 p-6"><p class="text-sm capitalize text-slate-400"><?= e($label) ?></p><b class="text-4xl"><?= is_float($value) ? money($value) : e($value) ?></b></div><?php endforeach; ?></div><section class="mt-8 rounded-3xl border border-white/10 bg-white/5 p-6"><h2 class="text-2xl font-black">Vendor Features</h2><div class="mt-5 grid gap-4 md:grid-cols-4"><?php foreach (['Upload products','Analytics charts','Earnings graph','Payout requests','Moderation status','Support messages','Review replies','Sales history'] as $feature): ?><div class="rounded-2xl bg-white/5 p-4 font-bold"><i class='bx bx-check text-cyan-300'></i> <?= e($feature) ?></div><?php endforeach; ?></div></section>
